import pytest
from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], *, workers: int = 4) -> int:
    """Return the sum of x*x for every x in xs.

    Squares are computed in a thread pool with `workers` threads. The result
    is identical for every worker count. Raises ValueError if workers < 1.
    The input list is not modified.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return sum(pool.map(square, xs))


@pytest.mark.parametrize(
    ("x", "expected"),
    [(0, 0), (1, 1), (-3, 9), (7, 49)],
)
def test_square(x: int, expected: int) -> None:
    assert square(x) == expected


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0


def test_sum_squares_small() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_sum_squares_negatives() -> None:
    assert sum_squares([-3, 4]) == 25


@pytest.mark.parametrize("workers", [1, 2, 3, 8, 32])
def test_sum_squares_same_at_every_worker_count(workers: int) -> None:
    xs = list(range(-500, 500))
    expected = sum(x * x for x in xs)
    assert sum_squares(xs, workers=workers) == expected


def test_sum_squares_does_not_mutate_input() -> None:
    xs = [1, -2, 3]
    before = list(xs)
    sum_squares(xs)
    assert xs == before


@pytest.mark.parametrize("workers", [0, -1])
def test_sum_squares_rejects_nonpositive_workers(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares([1, 2], workers=workers)
